package cn.dreamingfish.updater.management.cli.cloud;
import cn.dreamingfish.dispatch.server.model.*;import cn.dreamingfish.dispatch.server.model.ServerModels.*;import cn.dreamingfish.dispatch.server.real.ServerSecrets;
import javax.crypto.Mac;import javax.crypto.spec.SecretKeySpec;import java.nio.file.*;import java.sql.*;import java.time.*;import java.util.*;
/** 独立SQLite账号存储；所有SQL为固定模板，公开查询不含认证材料。 */
final class CloudAccountDatabase {
 record Login(Account account,String accessToken,String expiresAt){@Override public String toString(){return "Login[redacted]";}}
 private final Path file;private final byte[] sessionKey;private final String group;private final int timeout;
 CloudAccountDatabase(Path file,String sessionSecret,String group,int timeout){this.file=file;sessionKey=Base64.getUrlDecoder().decode(sessionSecret);this.group=group;this.timeout=Math.min(30000,timeout);if(!group.matches("[a-zA-Z0-9_-]{1,64}"))throw RemoteFailure.of("CONFIG_INVALID");
  try{ServerSecrets.safePath(file);Files.createDirectories(file.getParent());boolean existing=Files.exists(file)&&Files.size(file)>0;if(existing)checkOwnedDatabase();try(var c=open();var s=c.createStatement()){s.execute("PRAGMA journal_mode=WAL");s.execute("CREATE TABLE IF NOT EXISTS sqy_account_schema(version INTEGER NOT NULL)");if(!existing)s.execute("INSERT INTO sqy_account_schema VALUES(1)");s.execute("CREATE TABLE IF NOT EXISTS panel_accounts(id TEXT PRIMARY KEY,username TEXT UNIQUE NOT NULL,display_name TEXT NOT NULL,group_id TEXT NOT NULL,created_at TEXT NOT NULL,last_seen_at TEXT NOT NULL,salt BLOB NOT NULL,password_hash BLOB NOT NULL,password_version INTEGER NOT NULL,operation_id TEXT UNIQUE NOT NULL)");s.execute("CREATE TABLE IF NOT EXISTS panel_sessions(token_hash TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES panel_accounts(id),expires_at INTEGER NOT NULL)");s.execute("CREATE INDEX IF NOT EXISTS panel_sessions_expiry ON panel_sessions(expires_at)");}}
  catch(RemoteFailure e){throw e;}catch(Exception e){throw RemoteFailure.of("SERVER_ERROR");}
 }
 private void checkOwnedDatabase(){try{var config=new org.sqlite.SQLiteConfig();config.setReadOnly(true);try(var c=config.createConnection("jdbc:sqlite:"+file);var q=c.createStatement();var r=q.executeQuery("SELECT version FROM sqy_account_schema")){if(!r.next()||r.getInt(1)!=1||r.next())throw new SQLException();}}catch(Exception e){throw new RemoteFailure("CONFIG_INVALID","指定的数据库不属于本版本三秋叶账号服务；原文件保持不变");}}
 private Connection open()throws SQLException{var c=DriverManager.getConnection("jdbc:sqlite:"+file);try(var s=c.createStatement()){s.execute("PRAGMA foreign_keys=ON");s.execute("PRAGMA busy_timeout="+timeout);}return c;}
 private static Account account(ResultSet r)throws SQLException{return new Account(r.getString("id"),r.getString("username"),r.getString("display_name"),r.getString("group_id"),r.getString("created_at"),r.getString("last_seen_at"));}
 private static String user(String value){if(value==null||!value.matches("[a-z0-9_]{3,32}"))throw RemoteFailure.of("INVALID_DATA");return value;}
 private static void password(String value){if(value==null||value.codePointCount(0,value.length())<15||value.codePointCount(0,value.length())>128||value.indexOf(0)>=0)throw new RemoteFailure("INVALID_DATA","口令须为15至128个字符，可以使用空格和中文");}
 private String digest(String value){try{var mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(sessionKey,"HmacSHA256"));return HexFormat.of().formatHex(mac.doFinal(value.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(Exception e){throw RemoteFailure.of("SERVER_ERROR");}}
 synchronized Login register(String operation,String username,String display,String secret){user(username);password(secret);try{UUID.fromString(operation);}catch(Exception e){throw RemoteFailure.of("INVALID_DATA");}if(display==null||display.isBlank()||display.length()>64||display.chars().anyMatch(v->v<32))throw RemoteFailure.of("INVALID_DATA");byte[] salt=AccountPasswords.random(16),hash=AccountPasswords.derive(secret,salt);String now=Instant.now().toString();var a=new Account(UUID.randomUUID().toString(),username,display,group,now,now);
  try(var c=open()){c.setAutoCommit(false);try(var count=c.createStatement();var r=count.executeQuery("SELECT COUNT(*) FROM panel_accounts")){if(r.next()&&r.getLong(1)>=10000)throw RemoteFailure.of("SERVER_ERROR");}
   try(var p=c.prepareStatement("INSERT INTO panel_accounts VALUES(?,?,?,?,?,?,?,?,?,?)")){p.setString(1,a.id());p.setString(2,a.username());p.setString(3,a.displayName());p.setString(4,a.groupId());p.setString(5,now);p.setString(6,now);p.setBytes(7,salt);p.setBytes(8,hash);p.setInt(9,1);p.setString(10,operation);p.executeUpdate();}Login result=session(c,a);c.commit();return result;
  }catch(SQLException e){if(e.getErrorCode()==19)throw RemoteFailure.of("CONFLICT");throw RemoteFailure.of("SERVER_ERROR");}finally{Arrays.fill(hash,(byte)0);}
 }
 synchronized Login login(String username,String secret){user(username);password(secret);try(var c=open()){Account a=null;byte[] salt=new byte[16],expected=new byte[32];try(var p=c.prepareStatement("SELECT * FROM panel_accounts WHERE username=?")){p.setString(1,username);try(var r=p.executeQuery()){if(r.next()){a=account(r);salt=r.getBytes("salt");expected=r.getBytes("password_hash");if(r.getInt("password_version")!=1)throw RemoteFailure.of("SERVER_ERROR");}}}boolean matches=AccountPasswords.equal(AccountPasswords.derive(secret,salt),expected);if(a==null||!matches)throw RemoteFailure.of("AUTH_FAILED");c.setAutoCommit(false);a=seen(c,a);Login result=session(c,a);c.commit();return result;}catch(SQLException e){throw RemoteFailure.of("SERVER_ERROR");}}
 private Account seen(Connection c,Account a)throws SQLException{String now=Instant.now().toString();try(var p=c.prepareStatement("UPDATE panel_accounts SET last_seen_at=? WHERE id=?")){p.setString(1,now);p.setString(2,a.id());p.executeUpdate();}return new Account(a.id(),a.username(),a.displayName(),a.groupId(),a.createdAt(),now);}
 private Login session(Connection c,Account a)throws SQLException{long now=System.currentTimeMillis(),expires=now+8*3600*1000;String token=AccountPasswords.token();try(var p=c.prepareStatement("DELETE FROM panel_sessions WHERE expires_at<=?")){p.setLong(1,now);p.executeUpdate();}try(var p=c.prepareStatement("DELETE FROM panel_sessions WHERE account_id=? AND token_hash NOT IN (SELECT token_hash FROM panel_sessions WHERE account_id=? ORDER BY expires_at DESC LIMIT 19)")){p.setString(1,a.id());p.setString(2,a.id());p.executeUpdate();}try(var p=c.prepareStatement("INSERT INTO panel_sessions VALUES(?,?,?)")){p.setString(1,digest(token));p.setString(2,a.id());p.setLong(3,expires);p.executeUpdate();}return new Login(a,token,Instant.ofEpochMilli(expires).toString());}
 synchronized Account current(String token){if(token==null||!token.matches("[A-Za-z0-9_-]{43,128}"))throw RemoteFailure.of("AUTH_FAILED");try(var c=open();var p=c.prepareStatement("SELECT a.* FROM panel_accounts a JOIN panel_sessions s ON s.account_id=a.id WHERE s.token_hash=? AND s.expires_at>?")){p.setString(1,digest(token));p.setLong(2,System.currentTimeMillis());Account a;try(var r=p.executeQuery()){if(!r.next())throw RemoteFailure.of("AUTH_FAILED");a=account(r);}return seen(c,a);}catch(SQLException e){throw RemoteFailure.of("SERVER_ERROR");}}
 synchronized void logout(String token){current(token);try(var c=open();var p=c.prepareStatement("DELETE FROM panel_sessions WHERE token_hash=?")){p.setString(1,digest(token));p.executeUpdate();}catch(SQLException e){throw RemoteFailure.of("SERVER_ERROR");}}
 synchronized AccountDirectory list(){try(var c=open();var s=c.createStatement()){long total;try(var r=s.executeQuery("SELECT COUNT(*) FROM panel_accounts")){total=r.next()?r.getLong(1):0;}var result=new ArrayList<Account>();try(var r=s.executeQuery("SELECT id,username,display_name,group_id,created_at,last_seen_at FROM panel_accounts ORDER BY created_at DESC LIMIT 500")){while(r.next())result.add(account(r));}return new AccountDirectory(result,total,500,Instant.now().toString());}catch(SQLException e){throw RemoteFailure.of("SERVER_ERROR");}}
}
